SELECT id, user_id, title, status, processing_sequence_no, processing_deadline, selected_order_id,
       create_time, update_time
FROM ai_chat_session
WHERE id = #{sessionId}
  AND user_id = #{userId}
FOR UPDATE

mapper.update:
UPDATE ai_chat_session
SET status = 2,
    processing_sequence_no = #{processingSequenceNo},
    processing_deadline = #{processingDeadline},
    update_time = #{updateTime}
WHERE id = #{sessionId}
  AND user_id = #{userId}
  AND status = #{expectedStatus}

UPDATE ai_chat_session
SET status = 1,
    processing_sequence_no = NULL,
    processing_deadline = NULL,
    selected_order_id = COALESCE(#{selectedOrderId}, selected_order_id),
    update_time = #{updateTime}
WHERE id = #{sessionId}
  AND user_id = #{userId}
  AND status = 2
  AND processing_sequence_no = #{processingSequenceNo}

UPDATE ai_chat_session
SET status = 0,
    processing_sequence_no = NULL,
    processing_deadline = NULL,
    selected_order_id = NULL,
    update_time = #{updateTime}
WHERE id = #{sessionId}
  AND user_id = #{userId}
  AND status = #{expectedStatus}
